class Solution:
    def minimumBuckets(self, wells: List[List[int]], bucket_capacity: int) -> int:
        from collections import deque
        stack = deque()
        for row in wells:
            for col, unit in enumerate(row):
                if unit == 1:
                    stack.append((col, row))
        if not stack:
            return 0
        depth, buckets, waste = 0, 0, 0
        while stack:
            size = len(stack)
            for _ in range(size):
                col, row = stack.popleft()
                for r in (row + 1, row - 1):
                    if 0 <= r < len(wells) and wells[r][col] == 0:
                        wells[r][col] = depth + 1
                        stack.append((col, r))
                for c in (col + 1, col - 1):
                    if 0 <= c < len(wells[0]) and wells[row][c] == 0:
                        wells[row][c] = depth + 1
                        stack.append((c, row))
                wells[row][col] = -1
                waste += depth
            buckets += math.ceil(waste / bucket_capacity)
            depth += 1
        return buckets
